<section class="glass panel"><h2>Bulk assign activity terms</h2><p class="muted">Select activities, preview the destination term, then save. Scores are preserved; released grades stay unchanged until you publish again.</p>
<?php if (empty($book['config']['periods'])): ?><p class="academic-notice">Enable grading periods in Grading structure first.</p>
<?php elseif (!empty($book['locked'])): ?><p class="academic-notice">Reopen the finalized release before changing activity terms.</p>
<?php else: ?><form method="post" data-grade-dirty data-term-assignment class="stack-form"><?php render_grade_form_fields($book); ?><input type="hidden" name="action" value="assign_terms">
<div class="split-fields"><label><span>Filter component</span><select data-assign-component><option value="">All components</option><?php render_grading_category_options($book); ?></select></label><label><span>Filter current term</span><select data-assign-period><option value="">All terms</option><option value="unassigned">Unassigned</option><?php foreach (academic_periods() as $period): ?><option value="<?php echo esc($period['id']); ?>"><?php echo esc($period['name']); ?></option><?php endforeach; ?></select></label><label><span>Destination term</span><select name="period_id" required><?php render_period_options(is_string($_POST['period_id'] ?? null) ? $_POST['period_id'] : ''); ?></select></label></div>
<label class="grade-confirm"><input type="checkbox" data-assign-all><span>Select all visible activities</span></label>
<div class="academic-table-scroll"><table class="academic-table"><thead><tr><th>Select</th><th>Activity</th><th>Component</th><th>Current term</th><th>Recorded scores</th></tr></thead><tbody><?php foreach ($book['items'] as $id => $activity): if (!empty($activity['archived'])) continue; $recorded = count(array_filter($rows, fn($row) => ($row['items'][$id]['score'] ?? null) !== null)); ?><tr data-assign-row data-component="<?php echo esc($activity['category_id']); ?>" data-period="<?php echo esc($activity['period_id'] ?? 'unassigned'); ?>"><td><input type="checkbox" name="item_ids[]" value="<?php echo esc($id); ?>" aria-label="Select <?php echo esc($activity['name']); ?>" <?php echo in_array($id, is_array($_POST['item_ids'] ?? null) ? $_POST['item_ids'] : [], true) ? 'checked' : ''; ?>></td><th><?php echo esc($activity['name']); ?></th><td><?php echo esc(grading_category($book, $activity['category_id'])['name'] ?? ''); ?></td><td><?php echo esc(ucfirst($activity['period_id'] ?? 'Unassigned')); ?></td><td><?php echo $recorded; ?>/<?php echo count($students); ?></td></tr><?php endforeach; ?></tbody></table></div>
<label><span>Reason (required when recorded scores or published grades are affected)</span><input name="reason" maxlength="500" value="<?php echo esc(is_string($_POST['reason'] ?? null) ? $_POST['reason'] : ''); ?>"></label><p data-assignment-preview role="status">Select activities and a destination term.</p><button class="button button-primary" data-assign-save disabled>Save term assignments</button></form><?php endif; ?></section>
